"use client";

import { useState } from "react";
import { useSubmit } from "@/lib/api";
import { Card, Skeleton } from "@/components/finance";
import { useFinanceData } from "@/lib/api";
import { Button } from "@/components/finance";
import { Input } from "@/components/finance";
import { Slider } from "@/components/finance";
import { Empty } from "@/components/finance";

const ScenarioPage = () => {
  const [extraDebtPayment, setExtraDebtPayment] = useState<number>(0);
  const [salaryDelta, setSalaryDelta] = useState<number>(0);
  const [bonus, setBonus] = useState<number>(0);
  const [sipStepUp, setSipStepUp] = useState<number>(0);

  const submit = useSubmit<{ extraDebtPayment: number; salaryDelta: number; bonus: number; sipStepUp: number }>("/api/finance/scenario", "POST");

  const { data, isLoading, error, refetch } = useFinanceData<{ netWorthDelta: number; goalProbabilityDelta: number; }>("/api/finance/scenario");

  if (isLoading) return <Skeleton />;
  if (error) return <Empty />;

  return (
    <div>
      <h1>Scenario Lab</h1>
      <div>
        <h2>Extra Debt Payment</h2>
        <Slider value={extraDebtPayment} onChange={(value) => setExtraDebtPayment(value)} />
      </div>
      <div>
        <h2>Salary Delta</h2>
        <Slider value={salaryDelta} onChange={(value) => setSalaryDelta(value)} />
      </div>
      <div>
        <h2>Bonus</h2>
        <Slider value={bonus} onChange={(value) => setBonus(value)} />
      </div>
      <div>
        <h2>SIP Step-Up</h2>
        <Slider value={sipStepUp} onChange={(value) => setSipStepUp(value)} />
      </div>
      <Button onClick={() => submit({ extraDebtPayment, salaryDelta, bonus, sipStepUp }, { onSuccess: refetch })}>Simulate</Button>
      {data && (
        <div>
          <h2>Projected Net-Worth Delta</h2>
          <div>{data.netWorthDelta}</div>
          <h2>Goal Probability Delta</h2>
          <div>{data.goalProbabilityDelta}</div>
        </div>
      )}
    </div>
  );
};

export default ScenarioPage;
